<script setup lang="ts">
import type {Page,OrderDetail} from '@devstore/shared-types';import {money,dateTime,statusLabel} from '@devstore/ui/format';import {ArrowRight} from '@lucide/vue';
definePageMeta({middleware:'auth'});useSeoMeta({title:'我的订单 · DevStore'});const api=useApi();const {user}=useSession();const page=ref(1);const message=ref('');const busy=ref('');
const {data,error,status,refresh}=await useAsyncData(()=> 'private:orders:'+(user.value?.id||'none')+':'+page.value,()=>api.request<Page<OrderDetail>>('/orders?page='+page.value),{server:false});
async function cancel(id:string){busy.value=id;message.value='';try{await api.request('/orders/'+id+'/cancel',{method:'POST'});await refresh();}catch(e){message.value=e instanceof Error?e.message:'取消失败';}finally{busy.value='';}}
</script>
<template><div class="container"><div class="page-head"><span class="eyebrow">EVERY STEP, IN ONE PLACE</span><h1>我的订单</h1><p class="muted">查看付款审核与教程开通进度。</p></div><UserNav/><ClientOnly><ApiFeedback :pending="status==='pending'" :error="error" @retry="refresh"/><p v-if="message" role="alert" class="error">{{ message }}</p><template v-if="data&&!error"><div v-for="order in data.items" :key="order.id" class="panel order-card"><div class="spread"><div><span class="badge" :class="{green:order.status==='completed',purple:order.status==='payment_review'}">{{ statusLabel[order.status] }}</span><p class="order-info wrap">{{ order.order_no }} · {{ dateTime(order.created_at) }}</p><h2 style="font-size:18px;margin:0">{{ order.item.product_title }}</h2></div><span class="price">{{ money(order.amount_cents) }}</span></div><div class="row" style="justify-content:flex-end;margin-top:23px"><button v-if="order.status==='pending_payment'" class="btn secondary small" :disabled="busy===order.id" @click="cancel(order.id)">取消订单</button><NuxtLink :to="'/checkout/'+order.id" class="btn small">查看订单 <ArrowRight :size="14"/></NuxtLink></div></div><div v-if="!data.items.length" class="empty"><h2 style="font-size:21px;color:var(--ink)">还没有订单</h2><p>找到适合你的教程后，订单会显示在这里。</p><NuxtLink to="/tutorials" class="btn">去探索教程</NuxtLink></div><div v-if="data.total>20" class="pagination"><button class="btn secondary small" :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button class="btn secondary small" :disabled="page*20>=data.total" @click="page++">下一页</button></div></template></ClientOnly></div></template>
